/**
 * 당근 끌어올리기 규칙.
 *
 * 글마다 타겟 가격과 마감일이 있을 때만 가격을 내린다. 일정을 정한 날의 가격(시작가)에서
 * 타겟까지 날짜별로 균등한 직선을 긋고, 오늘 몫을 내림 단위로 맞춘다. 마지막 날은 타겟에
 * 맞춘다. 끌어올리기는 글당 15회·하루 6개 안에서, 쿨타임이 지났고 마지막 노출(끌올, 없으면 게시)이
 * 2일 이상 지난 글을 노출이 오래된 순으로 고른다. 하트 수는 같은 날짜끼리만 가른다.
 */

import { DAILY_BUMP_LIMIT, MAX_BUMPS } from "./cooldown";

/** 판매중 카드 한 장. 조회·채팅은 기록만 하고, 하트 수는 끌올 순서의 동점 처리에만 쓴다. */
export type Listing = {
	id: string;
	title: string;
	/** 지금 화면의 가격(원) */
	price: number;
	/** 하트 아이콘 옆 숫자 */
	hearts: number;
	views: number;
	chats: number;
	/** `끌올 N일 전`의 N. 끌올 문구가 없으면 null */
	bumpAgoDays: number | null;
	/** `N일 전`(게시 시점)의 N. 끌올한 적 없는 글의 노출 나이. 모르면 null */
	postedAgoDays?: number | null;
	/** 지금까지 끌어올린 횟수. 폰 문구를 못 읽었으면 null */
	bumpCount: number | null;
	/** 마지막 끌올 시각(ISO). 모르면 null */
	bumpedAt: string | null;
	/** 다음 끌올 가능 시각(ISO). 폰이 보여 준 값이 추정보다 우선한다 */
	nextBumpAt: string | null;
	/** 마감에 맞출 가격. 없으면 가격을 내리지 않는다 */
	target: number | null;
	/** 마감일 `YYYY-MM-DD`. 없으면 가격을 내리지 않는다 */
	until: string | null;
	/** 일정을 정한 날의 가격. 직선의 시작점. 없으면 지금 가격·오늘로 본다 */
	startPrice?: number | null;
	/** 일정을 정한 날 `YYYY-MM-DD` */
	startDate?: string | null;
	/** 실행에 넣는가 */
	included: boolean;
	/** 예약중 글. 끌올·가격 인하에서 빠진다 */
	reserved?: boolean;
};

/** 관리 화면에서 바꾸는 전역 설정. 가격 비율은 글의 타겟·날짜가 정한다. */
export type RuleSet = {
	dailyLimit: number;
};

export const DEFAULT_RULES: RuleSet = {
	dailyLimit: DAILY_BUMP_LIMIT,
};

/** 마지막 노출(끌올, 없으면 게시)이 이 일수 미만이면 아직 목록 위쪽이라 끌올 칸을 쓰지 않는다. */
export const MIN_BUMP_AGE_DAYS = 2;
/**
 * 마지막 노출이 이만큼 지난 글은 안 보이는 글이다. 가격만 내려도 사람이 못 보므로, 끌어올리는 날까지 인하를 미룬다.
 * 직선은 날짜로 그어져서 미룬 인하는 끌어올리는 날 한 번에 따라잡힌다.
 */
export const STALE_EXPOSURE_DAYS = 4;

export type Action = "bump" | "price-only";

/**
 * 오늘 끌올하지 못하는 까닭. 가격은 따로 내릴 수 있다.
 * fresh 마지막 노출이 2일 미만이다 / daily-limit 더 오래된 글이 하루 칸을 채웠다
 */
export type Blocked = "cooldown" | "max-bumps" | "fresh" | "daily-limit";

/** 건너뛰는 까닭. 끌올하지 못한 까닭이 있으면 그 값을 그대로 쓴다. */
export type SkipReason = "excluded" | "reserved" | Blocked;

/** 가격을 내리지 않고 끌어올리기만 하는 이유(타겟 도달). */
export type Note = "floor-reached" | null;

export type Proposal = {
	id: string;
	action: Action | "skip";
	/** 승인 가격. 내리지 않으면 현재가 */
	price: number;
	priceChanged: boolean;
	/** 오늘 인하분을 현재가 대비 %로 환산. 내리지 않으면 0 */
	ratio: number;
	skipReason: SkipReason | null;
	/** 끌어올리기 대상인데 끌올하지 못하는 까닭. 가격만 내리는 글에도 남는다 */
	blocked: Blocked | null;
	note: Note;
	/** 다음 끌올 가능 시각(ISO). 화면이 cooldown·max-bumps 안내에 쓴다 */
	nextBumpAt?: string | null;
};

export type ProposalSummary = {
	bump: number;
	priceOnly: number;
	skip: number;
	/** 끌어올리기 대상 중 하루 한도에 걸린 수 */
	held: number;
};

export type PricePoint = {
	date: string;
	price: number;
};

/**
 * 내림 단위. 경계는 인하 계산값(raw)을 기준으로 정한다.
 * 10,000원 미만 500원, 10만 원 미만 1,000원, 그 이상 5,000원.
 */
export function priceUnit(raw: number): 500 | 1000 | 5000 {
	if (raw < 10_000) return 500;
	if (raw < 100_000) return 1_000;
	return 5_000;
}

/** Asia/Seoul 달력의 `YYYY-MM-DD`. */
export function seoulToday(now = Date.now()): string {
	return new Intl.DateTimeFormat("en-CA", {
		timeZone: "Asia/Seoul",
		year: "numeric",
		month: "2-digit",
		day: "2-digit",
	}).format(new Date(now));
}

const ISO_DAY = /^\d{4}-\d{2}-\d{2}$/;

function seoulStart(iso: string): number {
	if (!ISO_DAY.test(iso)) return Number.NaN;
	return Date.parse(`${iso}T00:00:00+09:00`);
}

/** `from`부터 `to`까지 오늘을 포함한 날 수. 날짜가 아니면 null. */
export function remainingDays(from: string, to: string): number | null {
	const start = seoulStart(from);
	const end = seoulStart(to);
	if (Number.isNaN(start) || Number.isNaN(end)) return null;
	return Math.round((end - start) / 86_400_000) + 1;
}

export function addDays(iso: string, days: number): string {
	const start = seoulStart(iso);
	if (Number.isNaN(start)) return iso;
	return seoulToday(start + days * 86_400_000);
}

/** 하루 인하폭 `step`원 이하인 가장 굵은 내림 단위. 100원보다 잘게는 내리지 않는다. */
function stepUnit(step: number): number {
	for (const unit of [5_000, 1_000, 500]) if (step >= unit) return unit;
	return 100;
}

/**
 * 시작가에서 타겟까지 `days`일에 걸쳐 균등하게 내린 `index`번째(0부터) 날의 가격.
 * 마지막 날은 타겟을 다시 내림하지 않고, 그 전에는 타겟에 닿지 않는다. 날마다 시작가로 다시 재서 내림 오차가 쌓이지 않는다.
 */
export function linePrice(start: number, target: number, index: number, days: number): number {
	const total = days < 1 ? 1 : days;
	if (target <= 0 || target >= start) return start;
	if (index + 1 >= total) return target;
	const raw = start - ((start - target) * (index + 1)) / total;
	// 하루 인하폭보다 굵은 단위로 내리면 며칠씩 멈췄다 뛰므로, 단위를 인하폭 이하(최소 100원)로 낮춰 날마다 내려가게 한다.
	const unit = Math.min(priceUnit(raw), stepUnit((start - target) / total));
	return Math.min(start, Math.max(Math.floor(raw / unit) * unit, target + unit));
}

export type Schedule = {
	price: number;
	changed: boolean;
	ratio: number;
	remainingDays: number;
};

/** 시작가·시작일이 없으면 지금 가격·오늘이 시작이다. */
function lineOf(listing: Pick<Listing, "price" | "startPrice" | "startDate">, today: string) {
	const anchored = listing.startPrice != null && listing.startPrice > 0 && listing.startDate != null;
	return {
		startPrice: anchored ? (listing.startPrice as number) : listing.price,
		startDate: anchored ? (listing.startDate as string) : today,
	};
}

/** 타겟·마감이 없거나 날짜가 아니면 가격을 바꾸지 않는다. */
export function scheduleFor(listing: Listing, today: string): Schedule {
	if (listing.target === null || listing.target <= 0 || listing.until === null) {
		return { price: listing.price, changed: false, ratio: 0, remainingDays: 0 };
	}
	const left = remainingDays(today, listing.until);
	if (left === null) return { price: listing.price, changed: false, ratio: 0, remainingDays: 0 };
	const remaining = left < 1 ? 1 : left;
	const { startPrice, startDate } = lineOf(listing, today);
	const total = remainingDays(startDate, listing.until);
	if (total === null) return { price: listing.price, changed: false, ratio: 0, remainingDays: remaining };
	// 직선이 아직 시작하지 않았다(시작일이 내일 이후). 시작일 전에는 가격을 지킨다.
	if (startDate > today) return { price: listing.price, changed: false, ratio: 0, remainingDays: remaining };
	const index = Math.max(0, total - remaining);
	const planned = linePrice(startPrice, listing.target, index, total);
	// 직선보다 이미 낮으면 올리지 않는다.
	const changed = planned < listing.price && planned > 0;
	const price = changed ? planned : listing.price;
	const ratio = changed ? (100 * (listing.price - price)) / listing.price : 0;
	return { price, changed, ratio, remainingDays: remaining };
}

/** 오늘부터 마감까지 날짜별 가격. 시작가·시작일의 직선에서 읽는다. */
export function pricePath(
	start: { price: number; date: string },
	target: number,
	until: string,
	today: string,
): PricePoint[] {
	const total = remainingDays(start.date, until);
	const left = remainingDays(today, until);
	if (total === null || left === null) return [];
	const days = left < 1 ? 1 : left;
	const points: PricePoint[] = [];
	let date = today;
	for (let step = 0; step < days; step += 1) {
		const sinceStart = remainingDays(start.date, date) ?? 1;
		// 시작일 전에는 시작가를 지킨다. 시작일부터는 직선의 (시작일 기준) 몇 번째 날인지로 읽는다.
		points.push({
			date,
			price: sinceStart < 1 ? start.price : linePrice(start.price, target, sinceStart - 1, total),
		});
		date = addDays(date, 1);
	}
	return points;
}

export type FlowPoint = PricePoint & {
	/** 지금 화면의 가격 한 점. 직선의 날짜별 가격이 아니다 */
	current?: true;
};

/**
 * 가격 흐름의 맨 앞에 지금 가격을 붙인다. 오늘 직선 가격이 지금 가격과 다르면
 * (건너뛴 날이 쌓였거나 타겟을 새로 그은 때) `오늘`만 보여 주면 지금 가격에서 어떻게 가는지 읽히지 않는다.
 */
export function flowFromNow(price: number, path: PricePoint[]): FlowPoint[] {
	if (path.length === 0) return [];
	return path[0].price === price ? path : [{ date: path[0].date, price, current: true }, ...path];
}

/** 마지막 노출 후 지난 날. 끌올 문구가 있으면 그것, 없으면 게시 시점. 둘 다 못 읽었으면 null. */
export function exposureAgeDays(listing: Pick<Listing, "bumpAgoDays" | "postedAgoDays">): number | null {
	return listing.bumpAgoDays ?? listing.postedAgoDays ?? null;
}

